-- Migration number: 0002 	 2026-07-29T03:31:17.227Z

-- Catálogo de productos (fuente única de verdad para precios — antes solo
-- vivían en JSON del frontend, lo que permitía manipular el precio pagado
-- desde el navegador) y bandera de administrador.

CREATE TABLE IF NOT EXISTS products (
  codigo TEXT PRIMARY KEY,
  categoria TEXT NOT NULL, -- 'oftalmico' | 'sol'
  name TEXT NOT NULL,
  description TEXT,
  price REAL NOT NULL,
  brand TEXT NOT NULL,
  material TEXT,
  calibre TEXT,
  puente TEXT,
  varilla TEXT,
  caracteristicas TEXT,
  colores_disponibles TEXT, -- JSON array como texto
  images TEXT NOT NULL, -- JSON array como texto
  disponible INTEGER NOT NULL DEFAULT 1,
  destacado INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_products_categoria ON products (categoria);

ALTER TABLE users ADD COLUMN is_admin INTEGER NOT NULL DEFAULT 0;

